    holidays=["King's Day (April 27)", "Liberation Day (Bevrijdingsdag - May 5)", "National Remembrance Day (Dodenherdenking - May 4)", "Sinterklaas (Saint Nicholas Eve - December 5, traditional gift-giving with chocolate letters and spiced Pepernoten)", "Christmas Day and Boxing Day (December 25-26)", "New Year's Day (Nieuwjaarsduik - plunging into icy North Sea waves at Scheveningen)"],
