    worldHeritageSites=["Monastery of the Hieronymites and Tower of Belém in Lisbon (1983)", "Convent of Christ in Tomar (1983)", "Monastery of Batalha (1983)", "Historic Centre of Évora (1986)", "Cultural Landscape of Sintra (1995 - Pena Palace, Quinta da Regaleira)", "Historic Centre of Oporto, Luiz I Bridge and Monastery of Serra do Pilar (1996)", "Prehistoric Rock Art Sites in the Côa Valley", "Laurisilva of Madeira (1999)", "Alto Douro Wine Region (2001 - oldest demarcated wine region on Earth)", "Historic Centre of Guimarães (2001)", "Landscape of the Pico Island Vineyard Culture (Azores - 2004)", "Garrison Border Town of Elvas and its Fortifications (2012)", "University of Coimbra – Alta and Sofia (2013)", "Sanctuary of Bom Jesus do Monte in Braga (2019)", "Royal Building of Mafra (2019)"],
    unescoIntangible=["Fado, urban popular song of Portugal (2011)", "Mediterranean diet (2010)", "Cante Alentejano, polyphonic singing from Alentejo (2014)", "Manufacture of cowbells (2015)", "Falconry", "Craftmanship of Estremoz clay figures (2017)", "Black pottery of Bisalhães (2016)"],
    famousPeople=["Cristiano Ronaldo", "Vasco da Gama", "Fernando Pessoa", "Luís de Camões", "José Saramago", "Amália Rodrigues", "José Mourinho", "António Guterres", "Prince Henry the Navigator", "Paula Rego", "Marcelo Rebelo de Sousa"],
    flagDescription="Vertical bicolour of green (two-fifths of the width at the hoist, representing hope) and red (three-fifths of the width, representing the blood of patriots shed for the nation), with the national Coat of Arms (armillary sphere and Portuguese heraldic shield) centered along the division line.",
    coatOfArmsDescription="A silver shield bearing five blue escutcheons (Quinas), each charged with five silver bezants arranged in a saltire (symbolizing the five Moorish kings defeated by Afonso Henriques at Ourique and the five wounds of Christ), surrounded by a red border charged with seven golden castles (representing the fortified cities reclaimed from the Moors), all superimposed upon a golden armillary sphere (symbolizing Portugal's maritime discoveries) and bordered by two golden laurel branches tied with a green and red ribbon.",
    symbols={"bird": "Rooster of Barcelos (Galo de Barcelos - beloved folk symbol of faith, justice, and good luck)", "flower": "Red carnation (Cravo - symbol of the 1974 peaceful Carnation Revolution)", "tree": "Cork oak (Sobreiro - protected by national law since the 13th century)", "instrument": "Portuguese guitar (Guitarra portuguesa)"},
    landmarks=["Belém Tower and Jerónimos Monastery (Lisbon)", "Pena Palace and Quinta da Regaleira (Sintra)", "Dom Luís I Bridge and Ribeira Waterfront (Porto)", "Douro River Terraced Vineyards", "Benagil Sea Cave and Ponta da Piedade (Algarve)", "Batalha Monastery and Alcobaça Monastery", "University of Coimbra and Joanina Library", "Shrine of Our Lady of Fátima", "São Bento Railway Station (Porto - with 20,000 azulejo tiles)", "Big Wave at Nazaré (Praia do Norte)", "Sete Cidades Twin Lakes (Azores)"],
    travelNotes="Sip a velvety espresso alongside a warm, crispy Pastél de Belém dusted with cinnamon in Lisbon; take a day trip to Sintra to wander the vivid pastel towers of Pena Palace and the mystical initiation wells of Quinta da Regaleira; cruise down the Douro River through terraced vineyards tasting vintage Port wine; listen to haunting Fado in a candlelit Alfama tavern; watch colossal Atlantic waves crash into the cliffs of Nazaré.",
    shortSummary="Portugal is Europe's oldest nation-state, blessed with over 300 days of sunshine, famed for the maritime discoveries of Vasco da Gama, the soulful melodies of Fado, pastel-colored palaces of Sintra, delicious pastéis de nata, world-class Port wine, and 100% renewable energy achievements."
